"""Prepare a scientific article source, with citations in first-appearance order."""
from pathlib import Path
import re,json
BASE=Path(__file__).resolve().parent;ROOT=BASE.parent
MAP={int(k):v for k,v in json.loads((ROOT/'revision_12_2026-10-23/citation_number_map.json').read_text()).items()}
def renumber(text):
 def sub(m):
  ns=[int(x) for x in m[1].split(',')]
  return '['+','.join(str(MAP[n]) for n in ns)+']' if all(n in MAP for n in ns) else m[0]
 return re.sub(r'\[(\d+(?:\s*,\s*\d+)*)\]',sub,text)
def main():
 s=(BASE/'q1_manuscript_v11.md').read_text(encoding='utf-8')
 s=s.replace('The finite-element tests retain nominal sections and therefore omit material-removal effects on stiffness.','Interface and angular-mask controls delimit the discretization dependence. A separate eight-phase material-removal control gives approximately 0.4–2.1 nm centred changes outside contact, delimiting exact invariance to fixed compliance.')
 s=s.replace('Our contribution is the explicit connection between loaded contact support, exactly invariant relief sets and the sensitivity of the associated inverse operator.','Spitas et al. prescribe tooth-contact behaviour to synthesize a mating flank [41], whereas Kalligeros et al. infer geometrical deviations from double-flank radial measurements [42]. The present contribution is a pre-inversion observability diagnostic: loaded support defines invariant relief sets, a coupled-contact argument establishes their persistence under fixed elastic coupling, and contact tangents quantify the transition from exact invariance to weak information. It is not a new general framework for inverse gear analysis.')
 s=s.replace('Modified-profile contact studies link relief to load sharing, stiffness and transmission error [12,13].','Modified-profile contact studies link relief to load sharing, stiffness and transmission error [12,13]. Sánchez et al. also synthesize relief for prescribed load-sharing or transmission-error functions [12]. Such inverse design does not establish uniqueness when a manufactured relief must be inferred from a measured, centred response.')
 s=s.replace('They do not assess remeshed material removal.','A separate contour-modification experiment below changes the elastic domain itself. Its limited phase set and geometry differ from the gap-only inverse experiment; the two tests answer distinct questions.')
 s=s.replace('Q1_CROSS_INVERSE','Q1_CROSS_INVERSE\n\nQ1_DISCRETIZATION_V12')
 s=s.replace('## 4 Numerical results','A pre-inversion diagnostic follows from these results. First solve the zero-dedendum contact problem on the intended load and phase grid and compare its loaded-support minimum with the admissible relief starts. A region satisfying the sufficient condition defines an invariant parameter set before optimization. Where support overlaps relief, inspect the scaled tangent and nonlinear profiles rather than equating nonzero rank with usable precision. Finally compare the unrestricted fit with the addendum-only model and report the complete reconstructed profile. Each step concerns the same declared mechanical operator and retained observations; physical interpretation additionally requires an independent fidelity check.\n\n## 4 Numerical results')

 s=s.replace('The present fixed-section experiments do not provide that test. The results instead define what follows from the declared operator and identify which additional information physical reconstruction requires.','The modified-contour control tests the elastic consequence of removal while keeping the candidate contact geometry unchanged by construction. It is a controlled test of a theorem hypothesis, not a validation of a complete manufactured profile, contact transitions or inverse reconstruction. The results define what follows from the declared operator and identify which additional information physical reconstruction requires.')
 s=s.replace('It also retains nominal sections and cannot validate the influence of material removal on stiffness.','Physically modifying unloaded relief and reassembling stiffness gives approximately 0.4–2.1 nm centred differences in an eight-phase P2 control. Exact invariance therefore remains conditional on fixed compliance; the small physical effect does not validate profile inversion.')
 s=s.replace('The accompanying reproducibility package contains the analysis scripts, numerical records and checksums supporting the present results. The manuscript-v10 tag identifies the baseline deposit; the additional results require the accompanying package. No DOI is assigned to that package.','The accompanying MMT_reproducibility_v12.zip package contains the final article, supplementary tables, scripts, new numerical records, bibliographic verification and a SHA-256 manifest. The manuscript-v10 tag identifies only the historical baseline; the current additional evidence requires the version-12 package. The versioned package is deposited at https://github.com/romusan/gears-inversion-reproducibility/tree/manuscript-v12 with its numerical records and SHA-256 manifest. The historical v10 calculations are preserved separately; no DOI is assigned.')
 (BASE/'q1_manuscript_v12.md').write_text(renumber(s),encoding='utf-8')
if __name__=='__main__':main()
